// PI-201 压力高限联锁控制 valve1
// 当 PI-201 超过高限阈值时，自动置位 valve1

const HIGH_LIMIT = 100;  // 高限阈值，可根据实际工况调整

const pressure = get("PI-201");
const currentValveState = get("valve1");

if (pressure > HIGH_LIMIT && !currentValveState) {
    log("PI-201 压力过高: " + pressure + "，触发高限联锁，置位 valve1");
    set("valve1", true);
} else if (pressure <= HIGH_LIMIT && currentValveState) {
    log("PI-201 压力恢复正常: " + pressure + "，复位 valve1");
    set("valve1", false);
}

